UPDATE `agent_posts` SET `payload`=json_set(`payload`,'$.product','Pulito factory soaps: Pulito, Zote, Malibu, Nitsuh, Tval, Mydlo, Walif, Bon Savon, Zeyla','$.description','Laundry and bath soaps made from raw materials in our own factory in Ethiopia. We are looking for one or more agents in each city to buy and distribute our soaps to shops, kiosks and supermarkets.') WHERE `id`='AG-PULITO';